1	/**
2	 * Lightweight, dependency-free error logging.
3	 * Always writes a structured line to stderr (captured by journald); if
4	 * NXEON_ERROR_WEBHOOK is set, also POSTs a compact alert (best-effort).
5	 * Swap in Sentry later by adding a call here — this is the single choke point.
6	 */
7	type Level = "error" | "warn" | "info";
8	
9	export async function logEvent(
10	  level: Level,
11	  context: string,
12	  detail: Record<string, unknown> = {},
13	): Promise<void> {
14	  const line = {
15	    ts: new Date().toISOString(),
16	    level,
17	    context,
18	    ...detail,
19	    env: process.env.NXEON_ENV ?? "production",
20	  };
21	  const serialized = JSON.stringify(line);
22	  if (level === "error") console.error(`[nxeon] ${serialized}`);
23	  else if (level === "warn") console.warn(`[nxeon] ${serialized}`);
24	  else console.log(`[nxeon] ${serialized}`);
25	
26	  const webhook = process.env.NXEON_ERROR_WEBHOOK;
27	  if (webhook && level === "error") {
28	    // Fire-and-forget: never make a request wait on (or fail from) the outbound
29	    // alert. The caller does not await the fetch — only the stderr line above is
30	    // synchronous. Errors are swallowed so logging can never throw.
31	    void fetch(webhook, {
32	      method: "POST",
33	      headers: { "content-type": "application/json" },
34	      body: JSON.stringify({ text: `🚨 Nxeon ${context}: ${detail.message ?? "error"}`, detail: line }),
35	      signal: AbortSignal.timeout(3000),
36	    }).catch(() => {});
37	  }
38	}
39	
40	export function logError(context: string, error: unknown, extra: Record<string, unknown> = {}) {
41	  const e = error as { message?: string; stack?: string; digest?: string };
42	  return logEvent("error", context, {
43	    message: e?.message ?? String(error),
44	    stack: e?.stack?.split("\n").slice(0, 6).join("\n"),
45	    digest: e?.digest,
46	    ...extra,
47	  });
48	}
