1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
5	import { EmailLogViewer, type EmailLogRow } from "@/components/admin/EmailLogViewer";
6	import { actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";
7	
8	/**
9	 * Resolve the real admin behind any audit row taken while impersonating.
10	 * See the docblock on `actingAdminId` — `userId` stays the customer by design, so
11	 * every reader of the audit table has to do this or it credits the wrong person.
12	 */
13	async function actorEmails(logs: { detail: string | null }[]): Promise<Map<string, string>> {
14	  const ids = [...new Set(logs.map((l) => actingAdminId(l.detail)).filter(Boolean))] as string[];
15	  if (ids.length === 0) return new Map();
16	  const users = await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } });
17	  return new Map(users.map((u) => [u.id, u.email]));
18	}
19	
20	export const dynamic = "force-dynamic";
21	
22	type Tab = "audit" | "activity" | "email";
23	const TABS: { key: Tab; label: string }[] = [
24	  { key: "audit", label: "Audit" },
25	  { key: "activity", label: "Activity" },
26	  { key: "email", label: "Email" },
27	];
28	
29	export default async function AdminLogs({
30	  searchParams,
31	}: {
32	  searchParams: Promise<{ tab?: string }>;
33	}) {
34	  await requireArea("platform");
35	  const sp = await searchParams;
36	  const tab: Tab = (["audit", "activity", "email"] as const).includes(sp.tab as Tab)
37	    ? (sp.tab as Tab)
38	    : "audit";
39	
40	  return (
41	    <div className="space-y-6">
42	      <PageHeader title="Logs" sub="Audit trail, platform activity, and outbound email">
43	        <Badge tone="slate">platform</Badge>
44	      </PageHeader>
45	
46	      {/* Tabs */}
47	      <div className="flex gap-1 rounded-xl border border-white/[0.06] bg-white/[0.02] p-1">
48	        {TABS.map((t) => (
49	          <Link
50	            key={t.key}
51	            href={`/admin/logs?tab=${t.key}`}
52	            className={`rounded-lg px-4 py-1.5 text-sm font-medium transition-colors ${
53	              tab === t.key ? "bg-gradient-to-r from-accent-blue to-brand-500 text-white" : "text-slate-400 hover:text-white"
54	            }`}
55	          >
56	            {t.label}
57	          </Link>
58	        ))}
59	      </div>
60	
61	      {tab === "audit" && <AuditTab />}
62	      {tab === "activity" && <ActivityTab />}
63	      {tab === "email" && <EmailTab />}
64	    </div>
65	  );
66	}
