68	/* ---------------- Audit ---------------- */
69	
70	async function AuditTab() {
71	  const logs = await db.auditLog.findMany({
72	    include: { user: { select: { email: true, id: true } } },
73	    orderBy: { createdAt: "desc" },
74	    take: 200,
75	  });
76	  const actors = await actorEmails(logs);
77	
78	  return (
79	    <div className="card overflow-x-auto p-0">
80	      <table className="table-shell">
81	        <thead>
82	          <tr>
83	            <th>Time</th>
84	            <th>Actor</th>
85	            <th>Action</th>
86	            <th>Detail</th>
87	          </tr>
88	        </thead>
89	        <tbody>
90	          {logs.map((l) => {
91	            const asAdmin = actingAdminId(l.detail);
92	            const detail = asAdmin ? detailWithoutActor(l.detail) : (l.detail ?? "");
93	            return (
94	              <tr key={l.id}>
95	                <td className="whitespace-nowrap text-slate-400">
96	                  {l.createdAt.toISOString().replace("T", " ").slice(0, 19)}
97	                </td>
98	                <td>
99	                  {asAdmin ? (
100	                    <div className="flex flex-wrap items-center gap-2">
101	                      <Link href={`/admin/users/${asAdmin}`} className="hover:text-brand-300">
102	                        {actors.get(asAdmin) ?? asAdmin}
103	                      </Link>
104	                      <Badge tone="amber">impersonating {l.user?.email ?? "customer"}</Badge>
105	                    </div>
106	                  ) : l.user ? (
107	                    <Link href={`/admin/users/${l.user.id}`} className="hover:text-brand-300">
108	                      {l.user.email}
109	                    </Link>
110	                  ) : (
111	                    <span className="text-slate-500">system</span>
112	                  )}
113	                </td>
114	                <td className="font-mono text-xs">{l.action}</td>
115	                <td className="max-w-md truncate text-slate-400" title={detail}>
116	                  {detail}
117	                </td>
118	              </tr>
119	            );
120	          })}
121	        </tbody>
122	      </table>
123	    </div>
124	  );
125	}
