221	/* ---------------- Email ---------------- */
222	
223	async function EmailTab() {
224	  const rows = await db.emailLog.findMany({ orderBy: { createdAt: "desc" }, take: 200 });
225	  const logs: EmailLogRow[] = rows.map((r) => ({
226	    id: r.id,
227	    toEmail: r.toEmail,
228	    subject: r.subject,
229	    template: r.template,
230	    status: r.status,
231	    error: r.error,
232	    html: r.html,
233	    createdAt: r.createdAt.toISOString(),
234	  }));
235	  return <EmailLogViewer logs={logs} />;
236	}
