1	"use server";
2	
3	import { redirect } from "next/navigation";
4	import { revalidatePath } from "next/cache";
5	import { z } from "zod";
6	import { db } from "@/lib/db";
7	import { requireArea } from "@/lib/rbac";
8	import { logEvent } from "@/lib/log";
9	
10	type ActionState = { error?: string };
11	
12	const schema = z.object({
13	  id: z.string().optional(),
14	  author: z.string().min(1, "Author name is required.").max(80),
15	  role: z.string().max(120).optional(),
16	  quote: z.string().min(1, "Quote is required.").max(1000),
17	  avatarEmoji: z.string().max(8).optional(),
18	  rating: z.coerce.number().int().min(1).max(5).default(5),
19	  sortOrder: z.coerce.number().int().min(0).max(9999).default(0),
20	  published: z.boolean(),
21	});
22	
23	/** Create or update a testimonial. Wired to a <form> via useActionState. */
24	export async function saveTestimonial(
25	  _prev: ActionState,
26	  formData: FormData,
27	): Promise<ActionState> {
28	  await requireArea("platform");
29	
30	  const parsed = schema.safeParse({
31	    id: (formData.get("id") as string) || undefined,
32	    author: formData.get("author"),
33	    role: (formData.get("role") as string) || undefined,
34	    quote: formData.get("quote"),
35	    avatarEmoji: (formData.get("avatarEmoji") as string) || undefined,
36	    rating: formData.get("rating") ?? 5,
37	    sortOrder: formData.get("sortOrder") ?? 0,
38	    published: formData.get("published") === "on" || formData.get("published") === "true",
39	  });
40	
41	  if (!parsed.success) {
42	    return { error: parsed.error.issues[0]?.message ?? "Invalid testimonial." };
43	  }
44	
45	  const { id, role, avatarEmoji, ...rest } = parsed.data;
46	  const data = {
47	    ...rest,
48	    role: role || null,
49	    avatarEmoji: avatarEmoji || null,
50	  };
51	
52	  try {
53	    if (id) {
54	      const existing = await db.testimonial.findUnique({ where: { id } });
55	      if (!existing) return { error: "Testimonial not found." };
56	      await db.testimonial.update({ where: { id }, data });
57	    } else {
58	      await db.testimonial.create({ data });
59	    }
60	  } catch (err) {
61	    await logEvent("error", "testimonial.save", { message: String(err), author: data.author });
62	    return { error: "Could not save the testimonial. Please try again." };
63	  }
64	
65	  revalidatePath("/admin/testimonials");
66	  revalidatePath("/");
67	  redirect("/admin/testimonials");
68	}
69	
70	/** Flip a testimonial between hidden and published. */
71	export async function toggleTestimonialPublish(id: string): Promise<ActionState> {
72	  await requireArea("platform");
73	  const t = await db.testimonial.findUnique({ where: { id } });
74	  if (!t) return { error: "Testimonial not found." };
75	
76	  await db.testimonial.update({ where: { id }, data: { published: !t.published } });
77	
78	  revalidatePath("/admin/testimonials");
79	  revalidatePath("/");
80	  return {};
81	}
82	
83	/** Permanently delete a testimonial. */
84	export async function deleteTestimonial(id: string): Promise<ActionState> {
85	  await requireArea("platform");
86	  const t = await db.testimonial.findUnique({ where: { id } });
87	  if (!t) return { error: "Testimonial not found." };
88	
89	  await db.testimonial.delete({ where: { id } });
90	
91	  revalidatePath("/admin/testimonials");
92	  revalidatePath("/");
93	  return {};
94	}
