2	import assert from "node:assert/strict";
3	import { createHash } from "node:crypto";
4	import { readFileSync } from "node:fs";
5	import { redactEmailSecrets, REDACTED, emailLogRetentionDays } from "../lib/email-render.ts";
6	import { stripCommentsAndStrings } from "./_source-tools.ts";
