8	/**
9	 * Raw single-use tokens were persisted in plaintext in `EmailLog.html`.
10	 *
11	 * The chain, verified by reading the code (2026-07-27 auth audit):
12	 *   - `lib/actions-account.ts` and `lib/email-verification.ts` build reset /
13	 *     verification links carrying the RAW token; only its SHA-256 reaches the
14	 *     `*Token.tokenHash` column.
15	 *   - both call `sendMail({ html })` with that link embedded.
16	 *   - `lib/mailer.ts` calls `recordEmail(..., html, ...)` on EVERY path.
17	 *   - `recordEmail` wrote `html` verbatim into `EmailLog`.
18	 * Result: still-redeemable tokens sat in plaintext in the very database whose
19	 * compromise the `tokenHash` columns exist to survive. `EmailVerificationToken`'s
20	 * own schema comment claimed "a database leak hands out no working links" — false.
21	 *
22	 * The fix redacts secret-bearing query parameters at the single choke point
23	 * (`recordEmail`) so it cannot be forgotten per-template. These tests prove the
24	 * redaction by HASH, not by string: "the literal token is gone" passes trivially
25	 * if the value were merely reformatted, so we assert that no substring of the
26	 * stored body hashes to the real token.
27	 */
28	
29	const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");
30	
31	test("a reset link's token cannot be recovered from the redacted body", () => {
32	  // A real-shaped token: 32 random bytes, base64url — exactly what
33	  // `randomBytes(32).toString("base64url")` produces.
34	  const token = "u3Vn7xQpZ2-aB4cD6eF8gH0iJkLmN1oP3qR5sT7uV9w";
35	  const html = `<p>Reset your password:</p><a href="https://nxeon.cloud/reset-password?token=${token}">Reset</a>`;
36	  const stored = redactEmailSecrets(html);
37	
38	  // The redaction marker is present and the literal token is not.
39	  assert.match(stored, /token=\[redacted\]/);
40	  assert.ok(!stored.includes(token), "the literal token must be gone");
41	
42	  // The load-bearing assertion: no window of the stored body hashes to the token.
43	  // This catches a redaction that reformatted the token instead of removing it
44	  // (URL-encoding it, splitting it, leaving a prefix) — any of which would still
45	  // leave a redeemable value in the database.
46	  const want = sha256(token);
47	  for (let i = 0; i < stored.length; i++) {
48	    for (const len of [token.length, token.length - 1, token.length + 1]) {
49	      if (i + len <= stored.length && sha256(stored.slice(i, i + len)) === want) {
50	        assert.fail(`a substring of the stored body still hashes to the live token at index ${i}`);
51	      }
52	    }
53	  }
54	});
55	
56	test("every secret-bearing query parameter is redacted, not just token", () => {
57	  // The verification link uses ?token=; other flows use these. All must go, or
58	  // the choke point leaks the one it forgot.
59	  for (const param of ["token", "code", "key", "secret", "otp", "invite", "auth", "signature", "password", "pw"]) {
60	    const secret = "SECRETVALUE1234567890abcdefXYZ";
61	    const stored = redactEmailSecrets(`<a href="https://x/y?${param}=${secret}">go</a>`);
62	    assert.ok(!stored.includes(secret), `${param}= was not redacted`);
63	    assert.ok(stored.includes(`${param}=${REDACTED}`), `${param}= should read ${param}=[redacted]`);
64	  }
65	});
66	
67	test("redaction handles HTML-entity-encoded ampersands in a multi-param URL", () => {
68	  // Email HTML often encodes `&` as `&amp;`. A token that is the SECOND parameter
69	  // sits behind an encoded ampersand; the regex must still catch it, or a link
70	  // built as ...?uid=1&amp;token=SECRET leaks.
71	  const token = "aVeryRealLookingResetToken_0123456789";
72	  const stored = redactEmailSecrets(`<a href="https://x/verify?uid=42&amp;token=${token}">verify</a>`);
73	  assert.ok(!stored.includes(token), "a token behind &amp; must still be redacted");
74	  assert.match(stored, /token=\[redacted\]/);
75	  // The non-secret parameter is untouched — redaction removes secrets, not data.
76	  assert.match(stored, /uid=42/);
77	});
