79	test("ordinary links and content are left completely alone", () => {
80	  const html = '<a href="https://nxeon.cloud/dashboard/servers/abc123?tab=backups">Open</a><p>Your invoice total is $67.96.</p>';
81	  assert.equal(redactEmailSecrets(html), html, "a body with no secret parameter is unchanged");
