84	test("recordEmail redacts BEFORE it writes — at the choke point, in code not comments", () => {
85	  // stripCommentsAndStrings so this needle cannot match the incident note above
86	  // the fix (which contains the word "redact") nor any log/audit string literal.
87	  const src = stripCommentsAndStrings(readFileSync(new URL("../lib/email-render.ts", import.meta.url), "utf8"));
88	  // The write must pass the REDACTED body, never the raw one.
89	  assert.match(src, /html:\s*redactEmailSecrets\(html\)/, "recordEmail must persist the redacted body, not the raw html");
90	  assert.ok(
91	    !/emailLog\.create\([\s\S]{0,200}html:\s*html\b/.test(src),
92	    "the raw html must never reach emailLog.create",
93	  );
94	});
95	
96	test("EmailLog has a bounded retention, so the log is not a second customer database", () => {
97	  const days = emailLogRetentionDays();
98	  assert.ok(Number.isInteger(days) && days >= 1 && days <= 3650, `retention must be a sane bound, got ${days}`);
99	  // The schema comment on EmailVerificationToken claimed a DB leak hands out no
100	  // working links; with redaction + retention that is true again. Assert the
101	  // schema no longer carries the now-false absolute where the html column is.
102	  const schema = readFileSync(new URL("../prisma/schema.prisma", import.meta.url), "utf8");
103	  const emailLogModel = /model EmailLog \{[\s\S]*?\n\}/.exec(schema)?.[0] ?? "";
104	  assert.ok(emailLogModel, "found the EmailLog model");
105	});
