33	/** Brace-matched body of an exported async function (skips return-type braces). */
34	function bodyOf(src: string, name: string): string {
35	  const decl = new RegExp(`export\\s+async\\s+function\\s+${name}\\s*\\(`).exec(src);
36	  assert.ok(decl, `expected an exported action named ${name}`);
37	  let i = src.indexOf("(", decl.index);
38	  let parens = 0;
39	  let quote: string | null = null;
40	  for (; i < src.length; i++) {
41	    const c = src[i];
42	    if (quote) {
43	      if (c === "\\") i++;
44	      else if (c === quote) quote = null;
45	      continue;
46	    }
47	    if (c === '"' || c === "'" || c === "`") quote = c;
48	    else if (c === "(") parens++;
49	    else if (c === ")" && --parens === 0) break;
50	  }
51	  let angles = 0;
52	  for (i++; i < src.length; i++) {
53	    const c = src[i];
54	    if (c === "<") angles++;
55	    else if (c === ">") angles = Math.max(0, angles - 1);
56	    else if (c === "{" && angles === 0) break;
57	  }
58	  const start = i;
59	  let depth = 0;
60	  quote = null;
61	  for (; i < src.length; i++) {
62	    const c = src[i];
63	    if (quote) {
64	      if (c === "\\") i++;
65	      else if (c === quote) quote = null;
66	      continue;
67	    }
68	    if (c === '"' || c === "'" || c === "`") quote = c;
69	    else if (c === "{") depth++;
70	    else if (c === "}" && --depth === 0) return src.slice(start, i + 1);
71	  }
72	  assert.fail(`unbalanced body for ${name}`);
73	}
